// The same year as an interactive chart. Vega-Lite draws in the browser, so
// unlike a matplotlib picture it can do tooltips: hover a square to see that day.
const weather = nb.get('weather') ?? [];
const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const position = {
  x: { field: 'day', type: 'ordinal', title: 'Day of the month', axis: { labelAngle: 0, labelFontSize: 9 } },
  y: { field: 'month', type: 'ordinal', sort: months, title: null },
};

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  title: `Every day of the year. Dots are good picnic days; ${nb.get('best_month')} has the most.`,
  width: 640,
  height: 250,
  data: { values: weather },
  layer: [
    {
      mark: { type: 'rect', cornerRadius: 2 },
      encoding: {
        ...position,
        color: { field: 'high', type: 'quantitative', title: 'High °C', scale: { scheme: 'redyellowblue', reverse: true } },
        tooltip: [
          { field: 'month', title: 'Month' },
          { field: 'day', title: 'Day' },
          { field: 'high', title: 'High (°C)' },
          { field: 'rain', title: 'Rain (mm)' },
          { field: 'good', title: 'Picnic day?' },
        ],
      },
    },
    {
      transform: [{ filter: 'datum.good' }],
      mark: { type: 'circle', size: 16, color: '#052e16', opacity: 0.85 },
      encoding: position,
    },
  ],
};
